<?php
namespace Tests\Feature;
use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ProfileEmailTest extends TestCase {use RefreshDatabase;public function test_superuser_can_change_email_with_current_password():void{$this->seed();$token=$this->postJson('/api/v1/auth/login',['email'=>'admin@stockflow.local','password'=>'StockFlow@2026!'])->json('token');$h=['Authorization'=>'Bearer '.$token];$this->patchJson('/api/v1/account/profile',['name'=>'System Administrator','email'=>'new-admin@example.com','current_password'=>'wrong'],$h)->assertStatus(422);$this->patchJson('/api/v1/account/profile',['name'=>'System Administrator','email'=>'new-admin@example.com','current_password'=>'StockFlow@2026!'],$h)->assertOk()->assertJsonPath('data.email','new-admin@example.com');$this->getJson('/api/v1/auth/me',$h)->assertOk()->assertJsonPath('profile.email','new-admin@example.com');$this->postJson('/api/v1/auth/login',['email'=>'new-admin@example.com','password'=>'StockFlow@2026!'])->assertOk();}}
